<template>
  <main class="paper-shell"><div class="paper-container profile-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Author profile</div><h1 class="paper-page-title">{{ author.full_name||`Author ${route.params.id}` }}</h1><p class="paper-page-description">{{ author.current_affiliation||'Affiliation unavailable' }}<template v-if="author.orcid"> · ORCID <a :href="`https://orcid.org/${author.orcid}`" target="_blank" rel="noopener">{{ author.orcid }}</a></template></p><div v-if="author.institutions?.length" class="institution-tags"><NuxtLink v-for="institution in author.institutions" :key="institution" :to="{path:'/literature/institutions',query:{affiliation:institution}}">{{ institution }}</NuxtLink></div></div><NuxtLink class="paper-button" to="/literature/authors">All authors</NuxtLink></header><LiteratureKnowledgeNav />
    <p v-if="error" class="notice">{{ error }}</p><section class="profile-stats"><article><strong>{{ stats.total_papers||0 }}</strong><span>Papers</span></article><article><strong>{{ stats.total_citations||0 }}</strong><span>Citations</span></article><article><strong>{{ author.h_index||'—' }}</strong><span>h-index</span></article></section>
    <div class="profile-grid"><div class="profile-main"><section class="paper-panel"><div class="section-heading"><strong>Keyword distribution</strong></div><div v-if="topKeywords.length" class="keyword-cloud"><NuxtLink v-for="item in topKeywords" :key="item.keyword" :to="{path:'/literature',query:{q:item.keyword}}" :style="{fontSize:`${Math.min(18,11+Number(item.count||0))}px`}">{{ item.keyword }} <small>{{ item.count }}</small></NuxtLink></div><div v-else class="empty small">No keyword data.</div></section><section class="paper-panel"><div class="section-heading"><strong>Top collaborators</strong></div><NuxtLink v-for="item in coauthors" :key="item.id" class="coauthor" :to="`/literature/authors/${item.id}`"><span>{{ item.full_name }}</span><strong>{{ item.c||item.paper_count||0 }}</strong></NuxtLink><div v-if="!coauthors.length" class="empty small">No collaborator data.</div></section></div><aside class="profile-charts"><section class="paper-panel"><div class="section-heading"><strong>Year distribution</strong></div><div ref="yearChart" class="mini-chart"><div class="empty small">No year data.</div></div></section><section class="paper-panel"><div class="section-heading"><strong>Journal distribution</strong></div><div ref="journalChart" class="mini-chart"><div class="empty small">No journal data.</div></div></section></aside></div>
    <section class="paper-panel network-panel"><div class="section-heading"><strong>Collaboration network</strong><span>{{ network.nodes?.length||0 }} nodes</span></div><div ref="graph" class="profile-graph"><div class="empty">Loading network…</div></div></section>
    <section class="paper-panel papers"><div class="section-heading"><strong>Representative papers</strong><span>{{ papersData.total||papers.length }} total</span></div><table v-if="papers.length"><tbody><tr v-for="paper in papers" :key="paper.id" @click="router.push(`/literature/${paper.id}`)"><td>{{ paper.title }}</td><td>{{ paper.year||'—' }}</td><td>{{ paper.journal||'—' }}</td><td>{{ paper.citation_count||0 }} citations</td></tr></tbody></table><div v-else class="empty">No papers.</div><footer v-if="papers.length" class="paper-actions"><NuxtLink class="paper-button" :to="{path:'/literature',query:{author:author.full_name}}">View all {{ papersData.total||papers.length }} papers</NuxtLink><NuxtLink class="paper-button" :to="{path:'/literature/network',query:{focus_author:author.full_name}}">Locate papers in network</NuxtLink></footer></section>
  </div></main>
</template>
<script setup>
import '~/assets/paper-platform.css';import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),route=useRoute(),router=useRouter(),graph=ref(null),yearChart=ref(null),journalChart=ref(null),profile=ref({}),papersData=ref({}),network=ref({}),error=ref('');useHead(()=>({title:`${profile.value.author?.full_name||'Author'} - OpenIsle`}));const author=computed(()=>profile.value.author||{}),stats=computed(()=>profile.value.stats||{}),coauthors=computed(()=>profile.value.coauthors||[]),papers=computed(()=>papersData.value.papers||[]),topKeywords=computed(()=>stats.value.top_keywords||[])
const chartLabels={'common.no_data':'No data.','graph.paper':'Paper','graph.author':'Author','graph.keyword':'Keyword','graph.data_point':'Data point','graph.institution':'Institution','graph.no_nodes':'No relationship data.','graph.controls.title':'Graph controls','graph.controls.toggle':'Toggle graph controls','graph.controls.relayout':'Rebuild layout','graph.controls.reset':'Reset view','graph.controls.show_all_labels':'Show all labels','graph.controls.smart_labels':'Use smart labels','graph.legend.upstream':'Upstream','graph.legend.downstream':'Downstream','graph.legend.two_hop':'Two-hop neighbour','tooltip.type':'Type','tooltip.year':'Year','tooltip.citations':'Citations','tooltip.connections':'Connections','tooltip.occurrences':'Occurrences','tooltip.paper_count':'Paper count','tooltip.click_focus':'Click to focus; double-click to open'}
const charts=async()=>{window.Utils={...(window.Utils||{}),truncate:(v,n)=>String(v||'').slice(0,n),escapeHtml:v=>String(v||'')};const previousTranslate=window.I18n?.t?.bind(window.I18n);window.I18n={...(window.I18n||{}),t:key=>chartLabels[key]||(previousTranslate?previousTranslate(key):key)};if(window.OpenIsleLiteratureCharts)return window.OpenIsleLiteratureCharts;await new Promise((ok,bad)=>{const s=document.createElement('script');s.src='/literature-engine/charts.js';s.onload=ok;s.onerror=bad;document.head.appendChild(s)});return window.OpenIsleLiteratureCharts}
onMounted(async()=>{try{const base=`${config.public.apiBaseUrl}/api/literature/explore`;[profile.value,papersData.value,network.value]=await Promise.all([$fetch(`${base}/author/${route.params.id}`),$fetch(`${base}/author/${route.params.id}/papers?limit=10&offset=0`),$fetch(`${base}/author/${route.params.id}/network?max_nodes=40`)]);const c=await charts();c.forceGraph(graph.value,network.value.nodes||[],network.value.edges||[],{show_labels:true,onNodeClick:n=>{if(n.type==='author'&&n.author_id)router.push(`/literature/authors/${n.author_id}`);else if(n.type==='institution')router.push({path:'/literature/institutions',query:{affiliation:n.label}})}});if(stats.value.year_distribution?.length)c.barChart(yearChart.value,stats.value.year_distribution.map(item=>({label:item.year,value:item.c})),{height:220});if(stats.value.top_journals?.length)c.horizontalBar(journalChart.value,stats.value.top_journals.map(item=>({label:item.journal,value:item.c})),{height:Math.max(220,stats.value.top_journals.length*34+30)})}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load author profile.'}})
</script>
<style scoped>
.profile-container{max-width:1180px}.institution-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.institution-tags a{padding:4px 7px;background:var(--paper-surface-soft);color:var(--paper-teal);font-size:10px;font-weight:750;text-decoration:none}.profile-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-bottom:16px;border:1px solid var(--paper-line);background:var(--paper-line)}.profile-stats article{display:grid;gap:4px;padding:17px;background:#fff}.profile-stats strong{font:500 25px Georgia,serif}.profile-stats span{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.profile-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:16px;margin-bottom:16px}.profile-main,.profile-charts{display:grid;align-content:start;gap:16px}.section-heading{display:flex;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.network-panel{margin-bottom:16px}.profile-graph{height:520px;position:relative}.mini-chart{min-height:220px;padding:10px}.keyword-cloud{display:flex;flex-wrap:wrap;gap:8px;padding:16px}.keyword-cloud a{color:var(--paper-teal);text-decoration:none}.keyword-cloud small{color:var(--paper-muted)}.coauthor{display:flex;justify-content:space-between;padding:11px 15px;border-bottom:1px solid var(--paper-line);color:var(--paper-ink);text-decoration:none}.papers{overflow:hidden}.papers table{width:100%;border-collapse:collapse}.papers td{padding:12px 14px;border-bottom:1px solid var(--paper-line);font-size:12px}.papers tr{cursor:pointer}.paper-actions{display:flex;gap:8px;padding:13px 15px}.empty{display:grid;place-items:center;height:100%;min-height:100px;color:var(--paper-muted)}.empty.small{min-height:120px}.notice{padding:10px 14px;background:#fff4f2;color:#8b3028}@media(max-width:800px){.profile-grid{grid-template-columns:1fr}}
</style>
